// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface EducationIn {
  topic: string;
  method: "Verbal" | "Leaflet" | "WrittenInstructions" | "Demonstration" | "Video";
  given_to: "Patient" | "Attendant" | "Both";
  /** Required for Leaflet and Video; any active material otherwise */
  material_id?: number | null;
  /** The consultation it was part of */
  encounter_id?: number | null;
  note?: string | null;
}

export interface EducationOut {
  education_id: number;
  patient_id: number;
  mrn: string;
  patient_name: string;
  encounter_id: number | null;
  topic: string;
  method: "Verbal" | "Leaflet" | "WrittenInstructions" | "Demonstration" | "Video";
  material_id: number | null;
  material_title: string | null;
  given_to: "Patient" | "Attendant" | "Both";
  note: string | null;
  given_by: number;
  given_by_name: string;
  given_by_stamp: AuthorStampOut;
  given_at: string;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface MaterialOut {
  material_id: number;
  title: string;
  topic: string;
  kind: "Poster" | "Leaflet" | "Booklet" | "Video" | "Other";
  language: "Urdu" | "English" | "Punjabi" | "Other";
  displayed_at: string | null;
  is_active: boolean;
  row_version: number;
}

/** Record health education given — POST /api/v1/patients/{patient_id}/education (who may call: holders of education.give). */
export function recordPatientsEducation(patient_id: number, body: EducationIn): Promise<EducationOut> {
  return api<EducationOut>("POST", `/patients/${patient_id}/education`, body, { idempotent: true });
}

/** The education a patient was given — GET /api/v1/patients/{patient_id}/education (who may call: holders of education.give or education.manage). */
export function forPatientPatientsEducation(patient_id: number, query?: { limit?: number; before_id?: number | null }): Promise<EducationOut[]> {
  return api<EducationOut[]>("GET", withQuery(`/patients/${patient_id}/education`, query), undefined);
}

/** The education materials — GET /api/v1/education/materials (who may call: holders of education.give or education.manage or msds.view). */
export function listMaterials(query?: { include_inactive?: boolean }): Promise<MaterialOut[]> {
  return api<MaterialOut[]>("GET", withQuery(`/education/materials`, query), undefined);
}
